            THEN sched.try_lease('poller', coalesce(sched.setting_int('poller_lease_seconds'), 90)) ELSE false END AS got,
       (SELECT jsonb_object_agg(key, value) FROM sched.settings WHERE key NOT LIKE 'lease:%') AS settings;

